BEGIN;
SET LOCAL lock_timeout='10s';
LOCK TABLE "Workspace", "WorkspaceMember", "GymEnrollment", "GymGuardian", "GymInvoice", "GymContractAcceptance", "GymInvoiceItem", "GymPlan", "GymPlanVersion", "GymEnrollmentPause", "GymStudentProfile", "GymStaffProfile" IN ACCESS EXCLUSIVE MODE;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM "GymInvoice" c WHERE EXISTS (SELECT 1 FROM "Workspace" w WHERE w.id=c."workspaceId" AND w.type='GYM') AND NOT (EXISTS (SELECT 1 FROM "WorkspaceMember" m WHERE m.id=c."studentMemberId" AND m."workspaceId"=c."workspaceId" AND m."userId"=c."studentUserId") AND (c."enrollmentId" IS NULL OR EXISTS (SELECT 1 FROM "GymEnrollment" e WHERE e.id=c."enrollmentId" AND e."workspaceId"=c."workspaceId" AND e."studentMemberId"=c."studentMemberId")))) THEN RAISE EXCEPTION 'Reconcile GYM identity GymInvoice.identity before deployment'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM "GymEnrollment" c WHERE EXISTS (SELECT 1 FROM "Workspace" w WHERE w.id=c."workspaceId" AND w.type='GYM') AND NOT ((c."billingPayerGuardianId" IS NULL OR EXISTS (SELECT 1 FROM "GymGuardian" g WHERE g.id=c."billingPayerGuardianId" AND g."workspaceId"=c."workspaceId" AND g."studentMemberId"=c."studentMemberId")) AND (c."supersedesEnrollmentId" IS NULL OR EXISTS (SELECT 1 FROM "GymEnrollment" e WHERE e.id=c."supersedesEnrollmentId" AND e.id<>c.id AND e."workspaceId"=c."workspaceId" AND e."studentMemberId"=c."studentMemberId")))) THEN RAISE EXCEPTION 'Reconcile GYM identity GymEnrollment.identity before deployment'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM "GymContractAcceptance" c WHERE EXISTS (SELECT 1 FROM "Workspace" w WHERE w.id=c."workspaceId" AND w.type='GYM') AND NOT (EXISTS (SELECT 1 FROM "GymEnrollment" e JOIN "WorkspaceMember" m ON m.id=e."studentMemberId" WHERE e.id=c."enrollmentId" AND e."workspaceId"=c."workspaceId" AND ((c."representedUserId" IS NULL AND c."signerUserId"=m."userId") OR (c."representedUserId"=m."userId" AND c."signerUserId"<>m."userId" AND EXISTS (SELECT 1 FROM "GymGuardian" g WHERE g."workspaceId"=e."workspaceId" AND g."studentMemberId"=m.id AND g."guardianUserId"=c."signerUserId")))))) THEN RAISE EXCEPTION 'Reconcile GYM identity GymContractAcceptance.identity before deployment'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM "GymInvoiceItem" c JOIN "GymInvoice" own ON own.id=c."invoiceId" JOIN "Workspace" w ON w.id=own."workspaceId" WHERE w.type='GYM' AND c."planVersionId" IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM "GymInvoice" i JOIN "GymPlanVersion" v ON v.id=c."planVersionId" JOIN "GymPlan" p ON p.id=v."planId" WHERE i.id=c."invoiceId" AND i."workspaceId"=p."workspaceId"))) THEN RAISE EXCEPTION 'Reconcile GYM identity GymInvoiceItem.planVersionId before deployment'; END IF; END $$;
CREATE OR REPLACE FUNCTION atlasfit_gym_identity_gyminvoice() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF EXISTS (SELECT 1 FROM "Workspace" w WHERE w.id=NEW."workspaceId" AND w.type='GYM') AND NOT (EXISTS (SELECT 1 FROM "WorkspaceMember" m WHERE m.id=NEW."studentMemberId" AND m."workspaceId"=NEW."workspaceId" AND m."userId"=NEW."studentUserId") AND (NEW."enrollmentId" IS NULL OR EXISTS (SELECT 1 FROM "GymEnrollment" e WHERE e.id=NEW."enrollmentId" AND e."workspaceId"=NEW."workspaceId" AND e."studentMemberId"=NEW."studentMemberId"))) THEN RAISE EXCEPTION 'GYM identity relation mismatch: GymInvoice' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS gym_identity ON "GymInvoice";
CREATE TRIGGER gym_identity BEFORE INSERT OR UPDATE ON "GymInvoice" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_identity_gyminvoice();
CREATE OR REPLACE FUNCTION atlasfit_gym_identity_gymenrollment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF EXISTS (SELECT 1 FROM "Workspace" w WHERE w.id=NEW."workspaceId" AND w.type='GYM') AND NOT ((NEW."billingPayerGuardianId" IS NULL OR EXISTS (SELECT 1 FROM "GymGuardian" g WHERE g.id=NEW."billingPayerGuardianId" AND g."workspaceId"=NEW."workspaceId" AND g."studentMemberId"=NEW."studentMemberId")) AND (NEW."supersedesEnrollmentId" IS NULL OR EXISTS (SELECT 1 FROM "GymEnrollment" e WHERE e.id=NEW."supersedesEnrollmentId" AND e.id<>NEW.id AND e."workspaceId"=NEW."workspaceId" AND e."studentMemberId"=NEW."studentMemberId"))) THEN RAISE EXCEPTION 'GYM identity relation mismatch: GymEnrollment' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS gym_identity ON "GymEnrollment";
CREATE TRIGGER gym_identity BEFORE INSERT OR UPDATE ON "GymEnrollment" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_identity_gymenrollment();
CREATE OR REPLACE FUNCTION atlasfit_gym_identity_gymcontractacceptance() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF EXISTS (SELECT 1 FROM "Workspace" w WHERE w.id=NEW."workspaceId" AND w.type='GYM') AND NOT (EXISTS (SELECT 1 FROM "GymEnrollment" e JOIN "WorkspaceMember" m ON m.id=e."studentMemberId" WHERE e.id=NEW."enrollmentId" AND e."workspaceId"=NEW."workspaceId" AND ((NEW."representedUserId" IS NULL AND NEW."signerUserId"=m."userId") OR (NEW."representedUserId"=m."userId" AND NEW."signerUserId"<>m."userId" AND EXISTS (SELECT 1 FROM "GymGuardian" g WHERE g."workspaceId"=e."workspaceId" AND g."studentMemberId"=m.id AND g."guardianUserId"=NEW."signerUserId"))))) THEN RAISE EXCEPTION 'GYM identity relation mismatch: GymContractAcceptance' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS gym_identity ON "GymContractAcceptance";
CREATE TRIGGER gym_identity BEFORE INSERT OR UPDATE ON "GymContractAcceptance" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_identity_gymcontractacceptance();
CREATE OR REPLACE FUNCTION atlasfit_gym_invoice_item_scope() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF NEW."planVersionId" IS NOT NULL AND EXISTS (SELECT 1 FROM "GymInvoice" i JOIN "Workspace" w ON w.id=i."workspaceId" WHERE i.id=NEW."invoiceId" AND w.type='GYM') AND NOT (EXISTS (SELECT 1 FROM "GymInvoice" i JOIN "GymPlanVersion" v ON v.id=NEW."planVersionId" JOIN "GymPlan" p ON p.id=v."planId" WHERE i.id=NEW."invoiceId" AND i."workspaceId"=p."workspaceId")) THEN RAISE EXCEPTION 'GYM invoice item tenant relation mismatch' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS gym_invoice_item_scope ON "GymInvoiceItem";
CREATE TRIGGER gym_invoice_item_scope BEFORE INSERT OR UPDATE ON "GymInvoiceItem" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_invoice_item_scope();
CREATE OR REPLACE FUNCTION atlasfit_gym_reference_identity_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE old_scope text; new_scope text; BEGIN
IF to_jsonb(NEW)->>TG_ARGV[0] IS NOT DISTINCT FROM to_jsonb(OLD)->>TG_ARGV[0] THEN RETURN NEW; END IF;
EXECUTE format('SELECT "workspaceId" FROM %I WHERE id=$1',TG_ARGV[1]) INTO old_scope USING to_jsonb(OLD)->>TG_ARGV[0];
EXECUTE format('SELECT "workspaceId" FROM %I WHERE id=$1',TG_ARGV[1]) INTO new_scope USING to_jsonb(NEW)->>TG_ARGV[0];
IF EXISTS(SELECT 1 FROM "Workspace" WHERE id IN(old_scope,new_scope) AND type='GYM') THEN RAISE EXCEPTION 'GYM historical reference identity cannot be replaced' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS gym_reference_parent_immutable ON "GymInvoiceItem";
CREATE TRIGGER gym_reference_parent_immutable BEFORE UPDATE OF "invoiceId" ON "GymInvoiceItem" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_reference_identity_immutable('invoiceId','GymInvoice');
DROP TRIGGER IF EXISTS gym_reference_parent_immutable ON "GymEnrollmentPause";
CREATE TRIGGER gym_reference_parent_immutable BEFORE UPDATE OF "enrollmentId" ON "GymEnrollmentPause" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_reference_identity_immutable('enrollmentId','GymEnrollment');
DROP TRIGGER IF EXISTS gym_reference_parent_immutable ON "GymStudentProfile";
CREATE TRIGGER gym_reference_parent_immutable BEFORE UPDATE OF "memberId" ON "GymStudentProfile" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_reference_identity_immutable('memberId','WorkspaceMember');
DROP TRIGGER IF EXISTS gym_reference_parent_immutable ON "GymStaffProfile";
CREATE TRIGGER gym_reference_parent_immutable BEFORE UPDATE OF "memberId" ON "GymStaffProfile" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_reference_identity_immutable('memberId','WorkspaceMember');
DROP TRIGGER IF EXISTS gym_reference_parent_immutable ON "GymGuardian";
CREATE TRIGGER gym_reference_parent_immutable BEFORE UPDATE OF "studentMemberId" ON "GymGuardian" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_reference_identity_immutable('studentMemberId','WorkspaceMember');
DROP TRIGGER IF EXISTS gym_reference_parent_immutable ON "GymEnrollment";
CREATE TRIGGER gym_reference_parent_immutable BEFORE UPDATE OF "studentMemberId" ON "GymEnrollment" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_reference_identity_immutable('studentMemberId','WorkspaceMember');
DROP TRIGGER IF EXISTS gym_reference_parent_immutable ON "GymInvoice";
CREATE TRIGGER gym_reference_parent_immutable BEFORE UPDATE OF "studentMemberId" ON "GymInvoice" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_reference_identity_immutable('studentMemberId','WorkspaceMember');
CREATE OR REPLACE FUNCTION atlasfit_gym_member_identity_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF NEW."userId" IS DISTINCT FROM OLD."userId" AND EXISTS (SELECT 1 FROM "Workspace" WHERE id=OLD."workspaceId" AND type='GYM') THEN RAISE EXCEPTION 'GYM member identity cannot be replaced' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS gym_member_identity_immutable ON "WorkspaceMember";
CREATE TRIGGER gym_member_identity_immutable BEFORE UPDATE OF "userId" ON "WorkspaceMember" FOR EACH ROW EXECUTE FUNCTION atlasfit_gym_member_identity_immutable();
COMMIT;
